package com.portfolio.jobhub.controller;
import com.portfolio.jobhub.model.Job; import com.portfolio.jobhub.repo.JobRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/jobs") @CrossOrigin(origins="http://localhost:5173") public class JobController { private final JobRepository repo; public JobController(JobRepository r){repo=r;} @GetMapping public List<Job> all(@RequestParam(defaultValue="") String q){return q.isBlank()?repo.findAll():repo.search(q);} @GetMapping("/{id}") public ResponseEntity<Job> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Job> create(@Valid @RequestBody Job job){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(job));} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){repo.deleteById(id);return ResponseEntity.noContent().build();} }
